// tb_scheduler_correctness.sv
//
// Phase 13: correctness check for all 12 new-size scheduler-dataset
// programs (sim/programs/scheduler/*.s, generated by
// scheduler/benchmarks/gen_scheduler_programs.py) BEFORE any of their
// measured cycle counts are trusted as AI-scheduler training data --
// same "verify once, trust as benchmark thereafter" discipline as
// every prior benchmarking phase. Two of the six sizes checked here
// (N=64 vecadd/dot, N=8 matmul) are the accelerator's own MAX_LEN/
// MAX_DIM boundary -- worth verifying directly rather than assumed
// safe by extrapolation from Phase 9/10/11's smaller-N checks.
//
// Expected values computed in Python, not by hand (see
// scheduler/benchmarks/gen_scheduler_programs.py's own docstring and
// this project's repeated history of hand-derivation mistakes,
// documented throughout CHANGELOG.md):
//
//   python3 -c "
//   def vecadd(n): return [2*i+3 for i in range(n)]
//   def dot(n): return sum((i+1)*(i+2) for i in range(n))
//   def matmul(n):
//       A=[[i+j+1 for j in range(n)] for i in range(n)]
//       B=[[i+j+2 for j in range(n)] for i in range(n)]
//       return [sum(A[i][k]*B[k][j] for k in range(n))
//               for i in range(n) for j in range(n)]
//   print(vecadd(4), dot(4))
//   print(vecadd(64)[:4], '...', dot(64))
//   print(matmul(2))
//   print(matmul(8)[:4], '...')
//   "
//
// Twelve riscv_soc instances (six CPU-only, six accelerator-driven)
// run in parallel, same multi-DUT pattern as
// sim/testbenches/tb_perf_counters.sv (Phase 7) and
// tb_bench_cpu_correctness.sv (Phase 11).

`timescale 1ns/1ps

module tb_scheduler_correctness;

  logic clk;
  logic rst_n = 0;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  int errors = 0;

  task automatic check(string name, logic [31:0] actual, logic [31:0] expected);
    if (actual !== expected) begin
      $display("  [FAIL] %-28s expected=%0d actual=%0d", name, expected, actual);
      errors++;
    end else begin
      $display("  [PASS] %-28s = %0d", name, actual);
    end
  endtask

  task automatic check_sentinel(string name, logic [31:0] gpio_out);
    check({name, " sentinel"}, gpio_out, 32'hDEADBEEF);
  endtask

  `define SOC_PORTS(gpio_out_sig) \
    .clk(clk), .rst_n(rst_n), .gpio_in(32'b0), .gpio_out(gpio_out_sig), \
    .uart_tx_valid(), .uart_tx_byte(), \
    .dbg_if_pc(), .dbg_if_instr(), .dbg_id_pc(), .dbg_id_instr(), \
    .dbg_ex_pc(), .dbg_ex_instr(), .dbg_mem_instr(), .dbg_wb_instr(), \
    .dbg_reg_write(), .dbg_rd_addr(), .dbg_rd_data(), \
    .dbg_illegal(), .dbg_stall(), .dbg_flush(), \
    .perf_cycle_count(), .perf_instr_retired_count(), .perf_stall_count(), \
    .perf_branch_count(), .perf_branch_taken_count(), .perf_load_use_stall_count(), \
    .perf_forwarding_event_count(), .perf_flush_count()

  // -------------------------------------------------------------------
  // CPU-only instances
  // -------------------------------------------------------------------
  logic [31:0] cpu_va1_gpio, cpu_va4_gpio, cpu_va64_gpio, cpu_dot1_gpio, cpu_dot4_gpio, cpu_dot64_gpio;
  logic [31:0] cpu_mm2_gpio, cpu_mm8_gpio;

  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_vecadd_n1.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_va1 (`SOC_PORTS(cpu_va1_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_n1.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_dot1 (`SOC_PORTS(cpu_dot1_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_vecadd_n4.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_va4 (`SOC_PORTS(cpu_va4_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_vecadd_n64.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_va64 (`SOC_PORTS(cpu_va64_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_n4.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_dot4 (`SOC_PORTS(cpu_dot4_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_n64.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_dot64 (`SOC_PORTS(cpu_dot64_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_matmul_n2.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_mm2 (`SOC_PORTS(cpu_mm2_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_matmul_n8.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_mm8 (`SOC_PORTS(cpu_mm8_gpio));

  // -------------------------------------------------------------------
  // Accelerator-driven instances
  // -------------------------------------------------------------------
  logic [31:0] acc_va1_gpio, acc_va4_gpio, acc_va64_gpio, acc_dot1_gpio, acc_dot4_gpio, acc_dot64_gpio;
  logic [31:0] acc_mm2_gpio, acc_mm8_gpio;

  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_vecadd_n1.hex"))
    dut_acc_va1 (`SOC_PORTS(acc_va1_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_dot_n1.hex"))
    dut_acc_dot1 (`SOC_PORTS(acc_dot1_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_vecadd_n4.hex"))
    dut_acc_va4 (`SOC_PORTS(acc_va4_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_vecadd_n64.hex"))
    dut_acc_va64 (`SOC_PORTS(acc_va64_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_dot_n4.hex"))
    dut_acc_dot4 (`SOC_PORTS(acc_dot4_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_dot_n64.hex"))
    dut_acc_dot64 (`SOC_PORTS(acc_dot64_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_matmul_n2.hex"))
    dut_acc_mm2 (`SOC_PORTS(acc_mm2_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_matmul_n8.hex"))
    dut_acc_mm8 (`SOC_PORTS(acc_mm8_gpio));

  localparam int MAX_CYCLES = 40000; // matmul N=8 needs N^3=512 accel cycles
                                      // plus CPU setup/poll overhead; generous

  initial begin
    $display("=== Phase 13 scheduler-dataset program correctness check ===");

    rst_n = 0;
    repeat (2) @(posedge clk);
    #1;
    rst_n = 1;

    repeat (MAX_CYCLES) @(posedge clk);
    #1;

    // ---- CPU-only: vecadd N=1, dot N=1 (the real CPU-wins crossover
    // found for vecadd -- see docs/scheduler.md) ----
    $display("");
    $display("--- cpu_vecadd N=1, cpu_dot N=1 ---");
    check_sentinel("cpu_vecadd_n1", cpu_va1_gpio);
    check("va1 out[0]", dut_cpu_va1.ram_inst.mem[16'h0C00+0], 32'd3);
    check_sentinel("cpu_dot_n1", cpu_dot1_gpio);
    check("dot1 (x20)", dut_cpu_dot1.cpu_inst.regfile_inst.regs[20], 32'd2);

    // ---- CPU-only: vecadd N=4 ----
    $display("");
    $display("--- cpu_vecadd N=4 ---");
    check_sentinel("cpu_vecadd_n4", cpu_va4_gpio);
    check("out[0]", dut_cpu_va4.ram_inst.mem[16'h0C00+0], 32'd3);
    check("out[1]", dut_cpu_va4.ram_inst.mem[16'h0C00+1], 32'd5);
    check("out[2]", dut_cpu_va4.ram_inst.mem[16'h0C00+2], 32'd7);
    check("out[3]", dut_cpu_va4.ram_inst.mem[16'h0C00+3], 32'd9);

    // ---- CPU-only: vecadd N=64 (spot-check first/last) ----
    $display("");
    $display("--- cpu_vecadd N=64 ---");
    check_sentinel("cpu_vecadd_n64", cpu_va64_gpio);
    check("out[0]",  dut_cpu_va64.ram_inst.mem[16'h0C00+0],  32'd3);
    check("out[63]", dut_cpu_va64.ram_inst.mem[16'h0C00+63], 32'd129);

    // ---- CPU-only: dot N=4, N=64 ----
    $display("");
    $display("--- cpu_dot N=4, N=64 ---");
    check_sentinel("cpu_dot_n4", cpu_dot4_gpio);
    check("dot_n4 (x20)", dut_cpu_dot4.cpu_inst.regfile_inst.regs[20], 32'd40);
    check_sentinel("cpu_dot_n64", cpu_dot64_gpio);
    check("dot_n64 (x20)", dut_cpu_dot64.cpu_inst.regfile_inst.regs[20], 32'd91520);

    // ---- CPU-only: matmul N=2, N=8 ----
    $display("");
    $display("--- cpu_matmul N=2 ---");
    check_sentinel("cpu_matmul_n2", cpu_mm2_gpio);
    check("C[0]", dut_cpu_mm2.ram_inst.mem[16'h0C00+0], 32'd8);
    check("C[1]", dut_cpu_mm2.ram_inst.mem[16'h0C00+1], 32'd11);
    check("C[2]", dut_cpu_mm2.ram_inst.mem[16'h0C00+2], 32'd13);
    check("C[3]", dut_cpu_mm2.ram_inst.mem[16'h0C00+3], 32'd18);

    $display("");
    $display("--- cpu_matmul N=8 (spot-check corners) ---");
    check_sentinel("cpu_matmul_n8", cpu_mm8_gpio);
    check("C[0]",  dut_cpu_mm8.ram_inst.mem[16'h0C00+0],  32'd240);
    check("C[63]", dut_cpu_mm8.ram_inst.mem[16'h0C00+63], 32'd1192);

    // ---- Accelerator-driven: vecadd N=1, dot N=1 ----
    $display("");
    $display("--- accel_vecadd N=1, accel_dot N=1 ---");
    check_sentinel("accel_vecadd_n1", acc_va1_gpio);
    check("va1 vecout[0]", dut_acc_va1.accel_inst.vecout[0], 32'd3);
    check_sentinel("accel_dot_n1", acc_dot1_gpio);
    check("dot1 result_r", dut_acc_dot1.accel_inst.result_r, 32'd2);

    // ---- Accelerator-driven: vecadd N=4, N=64 ----
    $display("");
    $display("--- accel_vecadd N=4, N=64 ---");
    check_sentinel("accel_vecadd_n4", acc_va4_gpio);
    check("va4 vecout[0]", dut_acc_va4.accel_inst.vecout[0], 32'd3);
    check("va4 vecout[3]", dut_acc_va4.accel_inst.vecout[3], 32'd9);
    check_sentinel("accel_vecadd_n64", acc_va64_gpio);
    check("va64 vecout[0]",  dut_acc_va64.accel_inst.vecout[0],  32'd3);
    check("va64 vecout[63]", dut_acc_va64.accel_inst.vecout[63], 32'd129);

    // ---- Accelerator-driven: dot N=4, N=64 (RESULT register, MMIO offset 0xC) ----
    $display("");
    $display("--- accel_dot N=4, N=64 ---");
    check_sentinel("accel_dot_n4", acc_dot4_gpio);
    check("dot4 result_r", dut_acc_dot4.accel_inst.result_r, 32'd40);
    check_sentinel("accel_dot_n64", acc_dot64_gpio);
    check("dot64 result_r", dut_acc_dot64.accel_inst.result_r, 32'd91520);

    // ---- Accelerator-driven: matmul N=2, N=8 ----
    $display("");
    $display("--- accel_matmul N=2 ---");
    check_sentinel("accel_matmul_n2", acc_mm2_gpio);
    check("mm2 vecout[0]", dut_acc_mm2.accel_inst.vecout[0], 32'd8);
    check("mm2 vecout[1]", dut_acc_mm2.accel_inst.vecout[1], 32'd11);
    check("mm2 vecout[2]", dut_acc_mm2.accel_inst.vecout[2], 32'd13);
    check("mm2 vecout[3]", dut_acc_mm2.accel_inst.vecout[3], 32'd18);

    $display("");
    $display("--- accel_matmul N=8 (spot-check corners) ---");
    check_sentinel("accel_matmul_n8", acc_mm8_gpio);
    check("mm8 vecout[0]",  dut_acc_mm8.accel_inst.vecout[0],  32'd240);
    check("mm8 vecout[63]", dut_acc_mm8.accel_inst.vecout[63], 32'd1192);

    $display("");
    if (errors == 0) begin
      $display("RESULT: ALL CHECKS PASSED");
    end else begin
      $display("RESULT: %0d CHECK(S) FAILED", errors);
    end
    $finish;
  end

endmodule
